using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Serialization;
using BitigMail.Engine.Archive;
using BitigMail.Engine.Security;
using BitigMail.LocalHost.Security;

namespace BitigMail.LocalHost.Archive;
public enum RestoreReceiptState { Prepared, Published, Indexed, Failed }
public sealed record RestoreReceiptEntry(string SourceArchiveId, string FreshArchiveId, string StagingId, string ExpectedManifestSha256, int ExpectedMessageCount, long ExpectedTotalBytes, RestoreReceiptState State);
public sealed record RestoreReceipt(int Version, string OperationId, string ActorUserId, long SecurityVersion, string DestinationCompanyId, string DestinationProjectId, DateTimeOffset CreatedAtUtc, RestoreReceiptState State, IReadOnlyList<RestoreReceiptEntry> Entries, bool PayloadValidated = false);
public sealed record ArchiveRestoreResult(string OperationId, RestoreReceiptState State, IReadOnlyList<string> FreshArchiveIds, int MessageCount);

public sealed class ArchiveRestoreService
{
    private static readonly JsonSerializerOptions Json = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase, UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow, WriteIndented = true };
    private readonly ArchiveCatalogService _catalog; private readonly IdentityCatalog? _identities; private readonly string _receiptDir, _profileDirectory;
    public Func<string, CancellationToken, Task>? BeforePublishAsync { get; set; }
    public Func<string, CancellationToken, Task>? AfterPublishAsync { get; set; }
    public Func<string, CancellationToken, Task>? BeforeIndexAsync { get; set; }
    public Func<string, CancellationToken, Task>? AfterIndexAsync { get; set; }
    public ArchiveRestoreService(ArchiveCatalogService catalog, IdentityCatalog? identities = null) { _catalog = catalog; _identities = identities; _profileDirectory = Path.GetDirectoryName(catalog.StorageManager.ArchivesBaseDirectory)!; _receiptDir = Path.Combine(_profileDirectory, "restore-receipts"); RejectLinks(_receiptDir); Directory.CreateDirectory(_receiptDir); }
    public async Task<ArchiveRestoreResult> RestoreAsync(string packagePath, string companyId, string projectId, AuthenticatedSessionPrincipal actor, CancellationToken ct)
    {
        packagePath = Path.GetFullPath(packagePath); RejectLinks(packagePath); await using var input = new FileStream(packagePath, FileMode.Open, FileAccess.Read, FileShare.Read); ArchiveZipDirectoryPreflight.Validate(input, ct); input.Position = 0; using var zip = new ZipArchive(input, ZipArchiveMode.Read, true);
        var manifestEntry = zip.GetEntry("manifest.json") ?? throw new InvalidDataException("Yedek manifesti eksik."); byte[] manifestBytes = await ReadEntryBoundedAsync(manifestEntry, 16 * 1024 * 1024, ct);
        RejectDuplicateProperties(manifestBytes);
        var package = JsonSerializer.Deserialize<ArchiveBackupManifest>(manifestBytes, Json) ?? throw new InvalidDataException();
        if (package.Version != 1 || package.Archives is null || package.Files is null ||
            package.Archives.Count is < 1 or > 1000 || package.Files.Count is < 1 or > 99_999 ||
            package.IndexRebuildSchema != "BitigMail.ArchiveIndex.Rebuild.v1" ||
            package.Archives.Any(x => x is null) || package.Files.Any(x => x is null))
            throw new InvalidDataException("Yedek sürümü veya kapsamı geçersiz.");
        var sourceIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var archive in package.Archives)
        {
            ValidateId(archive.SourceArchiveId);
            if (!sourceIds.Add(archive.SourceArchiveId) || archive.MessageCount < 0 || archive.TotalBytes < 0 ||
                archive.ManifestSha256 is not { Length: 64 } || !archive.ManifestSha256.All(char.IsAsciiHexDigit))
                throw new InvalidDataException("Yedek arşiv tanımı geçersiz.");
        }
        foreach (var file in package.Files)
        {
            if (file.ArchiveId is null || !sourceIds.Contains(file.ArchiveId)) throw new InvalidDataException("Sahipsiz yedek dosyası.");
            ValidateRelative(file.RelativePath);
            if (file.PackagePath != $"archives/{file.ArchiveId}/{file.RelativePath.Replace('\\', '/')}")
                throw new InvalidDataException("Yedek dosya ilişkisi geçersiz.");
        }
        var expected = package.Files.Select(x => new ArchiveZipPayloadFile(x.PackagePath, x.Length, x.Sha256)).Append(new("manifest.json", manifestBytes.LongLength, Convert.ToHexString(SHA256.HashData(manifestBytes)))).ToArray(); var matched = ArchiveZipPayloadVerifier.MatchDirectory(zip, expected);
        string op = "restore_" + Guid.NewGuid().ToString("N"); var entries = package.Archives.Select(x => new RestoreReceiptEntry(x.SourceArchiveId, "arc_" + Guid.NewGuid().ToString("N"), "restore_" + Guid.NewGuid().ToString("N"), x.ManifestSha256, x.MessageCount, x.TotalBytes, RestoreReceiptState.Prepared)).ToArray(); var receipt = new RestoreReceipt(1, op, actor.UserId, actor.SecurityVersion, companyId, projectId, DateTimeOffset.UtcNow, RestoreReceiptState.Prepared, entries); SaveReceipt(receipt);
        try
        {
            var prepared = new Dictionary<string, ArchiveManifest>(StringComparer.Ordinal);
            foreach (var entry in entries) { ct.ThrowIfCancellationRequested(); RequireAccess(actor, companyId, projectId); var sourceArchive = package.Archives.Single(x => x.SourceArchiveId == entry.SourceArchiveId); var packageFiles = package.Files.Where(x => x.ArchiveId == entry.SourceArchiveId).ToArray(); var manifestFile = packageFiles.Single(x => x.RelativePath == "manifest.json"); byte[] sourceManifestBytes; await using (var ms = new MemoryStream()) { await ArchiveZipPayloadVerifier.CopyVerifiedAsync(matched[manifestFile.PackagePath], new(manifestFile.PackagePath, manifestFile.Length, manifestFile.Sha256), ms, ct); sourceManifestBytes = ms.ToArray(); } if (!Convert.ToHexString(SHA256.HashData(sourceManifestBytes)).Equals(sourceArchive.ManifestSha256, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException(); RejectDuplicateProperties(sourceManifestBytes); var sourceManifest = JsonSerializer.Deserialize<ArchiveManifest>(sourceManifestBytes, Json) ?? throw new InvalidDataException(); if (sourceManifest.ArchiveId != entry.SourceArchiveId || sourceManifest.TotalItems != entry.ExpectedMessageCount || sourceManifest.TotalSizeBytes != entry.ExpectedTotalBytes) throw new InvalidDataException("Kaynak manifest ilişkisi geçersiz."); ValidateMembership(sourceManifest, packageFiles); string staging = _catalog.StorageManager.CreateStagingDirectory(entry.StagingId); foreach (var file in packageFiles.Where(x => x.RelativePath != "manifest.json")) { ValidateRelative(file.RelativePath); string target = Path.GetFullPath(Path.Combine(staging, file.RelativePath)); if (!target.StartsWith(staging + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException(); Directory.CreateDirectory(Path.GetDirectoryName(target)!); await using var output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None); await ArchiveZipPayloadVerifier.CopyVerifiedAsync(matched[file.PackagePath], new(file.PackagePath, file.Length, file.Sha256), output, ct); await output.FlushAsync(ct); output.Flush(true); } sourceManifest.ArchiveId = entry.FreshArchiveId; sourceManifest.CompanyId = companyId; sourceManifest.ProjectId = projectId; sourceManifest.CompanyName = null; sourceManifest.ProjectName = null; await _catalog.StorageManager.WriteManifestAsync(staging, sourceManifest, ct); string rewrittenHash = HashFile(Path.Combine(staging, "manifest.json")); entries = entries.Select(x => x.FreshArchiveId == entry.FreshArchiveId ? x with { ExpectedManifestSha256 = rewrittenHash } : x).ToArray(); receipt = receipt with { Entries = entries }; SaveReceipt(receipt); prepared.Add(entry.FreshArchiveId, sourceManifest); }
            receipt = receipt with { PayloadValidated = true, Entries = entries }; SaveReceipt(receipt);
            // Admit every payload before publishing any archive from this package.
            foreach (var entry in entries) { ct.ThrowIfCancellationRequested(); var sourceManifest = prepared[entry.FreshArchiveId]; string staging = Path.Combine(_catalog.StorageManager.StagingBaseDirectory, entry.StagingId); RequireAccess(actor, companyId, projectId); if (BeforePublishAsync is not null) await BeforePublishAsync(entry.FreshArchiveId, ct); await using (var lease = await ProfileWriteLease.AcquireAsync(_profileDirectory, ct)) { RequireAccess(actor, companyId, projectId); SaveReceiptLocked(receipt); _catalog.StorageManager.PublishFreshStagingToManagedArchive(staging, entry.FreshArchiveId); if (AfterPublishAsync is not null) await AfterPublishAsync(entry.FreshArchiveId, ct); entries = entries.Select(x => x.FreshArchiveId == entry.FreshArchiveId ? x with { State = RestoreReceiptState.Published } : x).ToArray(); receipt = receipt with { State = RestoreReceiptState.Published, Entries = entries }; SaveReceiptLocked(receipt); } RequireAccess(actor, companyId, projectId); if (BeforeIndexAsync is not null) await BeforeIndexAsync(entry.FreshArchiveId, ct); RequireAccess(actor, companyId, projectId); await _catalog.SearchIndex.IndexArchiveAsync(sourceManifest, _catalog.StorageManager, null, ct); if (AfterIndexAsync is not null) await AfterIndexAsync(entry.FreshArchiveId, ct); entries = entries.Select(x => x.FreshArchiveId == entry.FreshArchiveId ? x with { State = RestoreReceiptState.Indexed } : x).ToArray(); receipt = receipt with { Entries = entries }; SaveReceipt(receipt); }
            receipt = receipt with { State = RestoreReceiptState.Indexed }; SaveReceipt(receipt); return new(op, receipt.State, entries.Select(x => x.FreshArchiveId).ToArray(), entries.Sum(x => x.ExpectedMessageCount));
        }
        catch { receipt = receipt with { State = RestoreReceiptState.Failed }; SaveReceipt(receipt); throw; }
    }
    public async Task<ArchiveRestoreResult> RepairAsync(string operationId, AuthenticatedSessionPrincipal actor, CancellationToken ct)
    {
        ValidateId(operationId); RestoreReceipt receipt = LoadReceipt(operationId); ValidateReceipt(receipt); if (!receipt.PayloadValidated) throw new InvalidDataException("Paket tam doğrulanmadan onarılamaz."); if (receipt.Version != 1 || receipt.ActorUserId != actor.UserId || receipt.SecurityVersion != actor.SecurityVersion) throw new UnauthorizedAccessException(); RequireAccess(actor, receipt.DestinationCompanyId, receipt.DestinationProjectId); var entries = receipt.Entries.ToArray();
        foreach (var entry in entries.Where(x => x.State != RestoreReceiptState.Indexed))
        {
            ct.ThrowIfCancellationRequested(); RequireAccess(actor, receipt.DestinationCompanyId, receipt.DestinationProjectId); if (string.IsNullOrWhiteSpace(entry.ExpectedManifestSha256)) throw new InvalidDataException("Onarım için hazırlanmış manifest özeti yok."); string published = Path.Combine(_catalog.StorageManager.ArchivesBaseDirectory, entry.FreshArchiveId); string staging = Path.Combine(_catalog.StorageManager.StagingBaseDirectory, entry.StagingId); ArchiveManifest manifest;
            if (Directory.Exists(published)) { manifest = VerifyOwnedManifest(published, entry, receipt); } else if (Directory.Exists(staging)) { manifest = VerifyOwnedManifest(staging, entry, receipt); await using var lease = await ProfileWriteLease.AcquireAsync(_profileDirectory, ct); if (!Directory.Exists(published)) _catalog.StorageManager.PublishFreshStagingToManagedArchive(staging, entry.FreshArchiveId); } else throw new InvalidDataException("Onarılabilir yayın veya hazırlık dizini bulunamadı.");
            RequireAccess(actor, receipt.DestinationCompanyId, receipt.DestinationProjectId); await _catalog.SearchIndex.IndexArchiveAsync(manifest, _catalog.StorageManager, null, ct); entries = entries.Select(x => x.FreshArchiveId == entry.FreshArchiveId ? x with { State = RestoreReceiptState.Indexed } : x).ToArray(); receipt = receipt with { State = entries.All(x => x.State == RestoreReceiptState.Indexed) ? RestoreReceiptState.Indexed : RestoreReceiptState.Published, Entries = entries }; SaveReceipt(receipt);
        }
        return new(receipt.OperationId, receipt.State, entries.Select(x => x.FreshArchiveId).ToArray(), entries.Sum(x => x.ExpectedMessageCount));
    }
    private void SaveReceipt(RestoreReceipt receipt) { using var lease = ProfileWriteLease.AcquireAsync(_profileDirectory, timeout: TimeSpan.FromSeconds(5)).GetAwaiter().GetResult(); SaveReceiptLocked(receipt); }
    private void SaveReceiptLocked(RestoreReceipt receipt) { ValidateId(receipt.OperationId); RejectLinks(_receiptDir); string path = Path.Combine(_receiptDir, receipt.OperationId + ".json"), temp = path + "." + Guid.NewGuid().ToString("N") + ".tmp"; try { using (var stream = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { JsonSerializer.Serialize(stream, receipt, Json); stream.Flush(true); } File.Move(temp, path, true); } finally { try { if (File.Exists(temp)) File.Delete(temp); } catch { } } }
    private RestoreReceipt LoadReceipt(string operationId) { string path = Path.Combine(_receiptDir, operationId + ".json"); RejectLinks(path); using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read); if (stream.Length is < 1 or > 1_048_576) throw new InvalidDataException(); byte[] bytes = new byte[stream.Length]; stream.ReadExactly(bytes); RejectDuplicateProperties(bytes); return JsonSerializer.Deserialize<RestoreReceipt>(bytes, Json) ?? throw new InvalidDataException(); }
    private ArchiveManifest VerifyOwnedManifest(string directory, RestoreReceiptEntry entry, RestoreReceipt receipt) { RejectLinks(directory); string path = Path.Combine(directory, "manifest.json"); if (!HashFile(path).Equals(entry.ExpectedManifestSha256, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException("Onarım hedefi beklenen manifest ile uyuşmuyor."); var manifest = JsonSerializer.Deserialize<ArchiveManifest>(File.ReadAllBytes(path), Json) ?? throw new InvalidDataException(); if (manifest.ArchiveId != entry.FreshArchiveId || manifest.CompanyId != receipt.DestinationCompanyId || manifest.ProjectId != receipt.DestinationProjectId || manifest.TotalItems != entry.ExpectedMessageCount || manifest.TotalSizeBytes != entry.ExpectedTotalBytes) throw new InvalidDataException("Onarım hedef kimliği veya kapsamı uyuşmuyor."); foreach (var item in manifest.Items) { ValidateRelative(item.RelativeEmlPath); string raw = Path.GetFullPath(Path.Combine(directory, item.RelativeEmlPath)); if (!raw.StartsWith(Path.GetFullPath(directory) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) || new FileInfo(raw).Length != item.ByteLength || !HashFile(raw).Equals(item.StoredSha256, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException("Onarım ham ileti doğrulaması başarısız."); } return manifest; }
    private static void ValidateReceipt(RestoreReceipt receipt) { ValidateId(receipt.OperationId); ValidateId(receipt.ActorUserId); ValidateId(receipt.DestinationCompanyId); ValidateId(receipt.DestinationProjectId); if (receipt.Version != 1 || receipt.SecurityVersion < 0 || receipt.Entries.Count is < 1 or > 1000 || !Enum.IsDefined(receipt.State)) throw new InvalidDataException("Onarım makbuzu geçersiz."); var archives = new HashSet<string>(StringComparer.OrdinalIgnoreCase); var staging = new HashSet<string>(StringComparer.OrdinalIgnoreCase); foreach (var entry in receipt.Entries) { ValidateId(entry.SourceArchiveId); ValidateId(entry.FreshArchiveId); ValidateId(entry.StagingId); if (!archives.Add(entry.FreshArchiveId) || !staging.Add(entry.StagingId) || entry.ExpectedMessageCount < 0 || entry.ExpectedTotalBytes < 0 || !Enum.IsDefined(entry.State) || entry.ExpectedManifestSha256.Length != 64 || entry.ExpectedManifestSha256.Any(c => !Uri.IsHexDigit(c))) throw new InvalidDataException("Onarım makbuzu girdisi geçersiz."); } }
    private void RequireAccess(AuthenticatedSessionPrincipal actor, string company, string project) { if (_identities is not null && (!_identities.IsAdmin(actor) || !_identities.CanAccess(actor, company, project))) throw new UnauthorizedAccessException(); }
    private static void ValidateMembership(ArchiveManifest manifest, ArchiveBackupFile[] files) { var payload = files.Where(x => x.RelativePath != "manifest.json").ToDictionary(x => x.RelativePath, StringComparer.OrdinalIgnoreCase); if (payload.Count != manifest.Items.Count) throw new InvalidDataException("Yedek dosya/manifest üyeliği uyuşmuyor."); var ord = new HashSet<int>(); foreach (var item in manifest.Items) { ValidateRelative(item.RelativeEmlPath); if (!ord.Add(item.Ordinal) || !payload.TryGetValue(item.RelativeEmlPath, out var file) || file.Length != item.ByteLength || !file.Sha256.Equals(item.StoredSha256, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException("Yedek ileti ilişkisi geçersiz."); } }
    private static void ValidateRelative(string value) { BitigMail.Engine.Distribution.PackagePayloadValidator.ValidateRelativePath(value); if (value != value.Normalize(System.Text.NormalizationForm.FormC)) throw new InvalidDataException(); }
    private static async Task<byte[]> ReadEntryBoundedAsync(ZipArchiveEntry entry, int maximum, CancellationToken ct) { if (entry.Length is < 1 || entry.Length > maximum) throw new InvalidDataException(); await using var source = entry.Open(); using var output = new MemoryStream((int)entry.Length); byte[] buffer = new byte[64 * 1024]; while (true) { int read = await source.ReadAsync(buffer, ct); if (read == 0) break; if (output.Length + read > maximum) throw new InvalidDataException(); await output.WriteAsync(buffer.AsMemory(0, read), ct); } if (output.Length != entry.Length) throw new InvalidDataException(); return output.ToArray(); }
    private static string HashFile(string path) { using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read); return Convert.ToHexString(SHA256.HashData(stream)); }
    private static void ValidateId(string value) { if (string.IsNullOrWhiteSpace(value) || value.Length > 128 || value.Any(c => !(char.IsAsciiLetterOrDigit(c) || c is '_' or '-'))) throw new InvalidDataException("Geçersiz kimlik."); }
    private static void RejectDuplicateProperties(byte[] json) { using var doc = JsonDocument.Parse(json, new JsonDocumentOptions { MaxDepth = 32 }); Walk(doc.RootElement); static void Walk(JsonElement value) { if (value.ValueKind == JsonValueKind.Object) { var names = new HashSet<string>(StringComparer.Ordinal); foreach (var p in value.EnumerateObject()) { if (!names.Add(p.Name)) throw new InvalidDataException("Yinelenen JSON alanı."); Walk(p.Value); } } else if (value.ValueKind == JsonValueKind.Array) foreach (var item in value.EnumerateArray()) Walk(item); } }
    private static void RejectLinks(string path) { for (string? current = Path.GetFullPath(path); current is not null; current = Path.GetDirectoryName(current)) if ((File.Exists(current) || Directory.Exists(current)) && (File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0) throw new InvalidDataException("Bağlantılı paket yolu kabul edilmez."); }
}
